for a in alphas:
    print(f"alpha={a:.4f}, N={get_N_for_alpha(a)}")

import math

def get_N_for_alpha(alpha, limit=100):
    N = 0
    for x in range(limit):
        for y in range(limit):
            val = x + alpha * y
            rank = 0
            # Only need (x', y') such that x' + alpha*y' < val
            # x' < val - alpha*y'
            # We need to find the range of y'
            max_y_prime = int(val // alpha)
            for y_prime in range(max_y_prime + 1):
                if y_prime == y:
                    rank += x
                else:
                    rank += int(math.floor(val - alpha * y_prime + 1e-11)) + 1
            if rank % 2 == 1:
                N += 1
    return N

